SEEDS = {"balanced": 2026092110, "activation_heavy": 2026092100,
         "service_heavy": 2026092120}

def costs(profile):
    rng = random.Random(SEEDS[profile])
    fixed, marginal = [], []
    for m in range(6):
        if profile == "balanced":
            h, c = 1.5 + .5 * (m + 1), .05 + .035 * m
        elif profile == "activation_heavy":
            h, c = 4.0 + 1.2 * (m + 1) ** 1.25, .02 + .008 * m
        else:
            h, c = .2 + .1 * m, .10 + .075 * m
        fixed.append(F(str(round(h * rng.uniform(.95, 1.05), 9))))
        marginal.append(F(str(round(c * rng.uniform(.95, 1.05), 9))))
    return tuple(fixed), tuple(marginal)
